const getPredictedCategory = async (description) => {
  try {
    const response = await fetch("http://127.0.0.1:5000/predict", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ description }),
    });

    if (!response.ok) {
      throw new Error("Network response was not ok");
    }

    const data = await response.json();
    return data.category;  // Assuming your Flask API returns { "category": "Bills" }
  } catch (error) {
    console.error("Error while predicting category:", error);
    return "";
  }
};


const AddTransaction = () => {
  const auth = getAuth();
const [userId, setUserId] = useState(null);

// Fetch user ID on mount
useEffect(() => {
  const unsubscribe = auth.onAuthStateChanged((user) => {
    if (user) {
      setUserId(user.uid);
    } else {
      setUserId(null);
    }
  });

  return () => unsubscribe(); // Cleanup listener on unmount
}, []);

  const [amount, setAmount] = useState("");
  const [category, setCategory] = useState("");
  const [date, setDate] = useState("");
  const [note, setNote] = useState("");
  const [description, setDescription] = useState("");
  const [suggestedCategory, setSuggestedCategory] = useState("");
  const [showSuccessMessage, setShowSuccessMessage] = useState(false); // State for showing success message
  
  // Income fields
  const [incomeSource, setIncomeSource] = useState("");
  const [incomeAmount, setIncomeAmount] = useState("");
  const [incomeDate, setIncomeDate] = useState("");

  // Recurring fields
  const [isRecurring, setIsRecurring] = useState(false);
  const [recurringFrequency, setRecurringFrequency] = useState("monthly");

  // Udhar (Loan) fields
  const [isUdhar, setIsUdhar] = useState(false);
  const [loanType, setLoanType] = useState("borrow");
  const [loanAmount, setLoanAmount] = useState("");
  const [repaymentDate, setRepaymentDate] = useState("");

  // Party Involved field
  const [partyInvolved, setPartyInvolved] = useState("");

  useEffect(() => {
    // Suggest category based on the description
    // if (description && !category) {
    //   const suggested = getSuggestedCategory(description);
    //   setSuggestedCategory(suggested);
    // }
  
    // Fetch predicted category from Flask API if description is available
    const fetchPredictedCategory = async () => {
      if (description && !category) {
        const predicted = await getPredictedCategory(description);
        setSuggestedCategory(predicted);
      }
    };
  
    fetchPredictedCategory();
  }, [description, category]);
  





  const handleTransactionSubmit = (e) => {
    e.preventDefault();
  
    if (!userId) {
      alert("User not authenticated. Please log in.");
      return;
    }
  
    if (!amount || (!category && !suggestedCategory) || !date) {
      alert("Please fill in all required fields: Amount, Category, and Date.");
      return;
    }
  
    const transaction = {
      amount: parseFloat(amount),
      category: category || suggestedCategory,
      date,
      note,
      description,
      isRecurring,
      recurringFrequency: isRecurring ? recurringFrequency : null,
      isUdhar,
      loanType: isUdhar ? loanType : null,
      loanAmount: isUdhar ? parseFloat(loanAmount) : null,
      repaymentDate: isUdhar ? repaymentDate : null,
      partyInvolved,
    };
  
    // Store transactions inside the user's node
    const transactionRef = ref(database, `users/${userId}/transactions`);
    push(transactionRef, transaction)
      .then(() => {
        setShowSuccessMessage(true);
        setTimeout(() => setShowSuccessMessage(false), 3000);
        setAmount("");
        setCategory("");
        setDate("");
        setNote("");
        setDescription("");
        setSuggestedCategory("");
        setIsRecurring(false);
        setRecurringFrequency("monthly");
        setIsUdhar(false);
        setLoanType("");
        setLoanAmount("");
        setRepaymentDate("");
        setPartyInvolved("");
      })
      .catch((error) => {
        console.error("Error adding transaction:", error);
        alert("Failed to add transaction. Please try again.");
      });
  };
  
  

  const handleIncomeSubmit = (e) => {
    e.preventDefault();
  
    if (!userId) {
      alert("User not authenticated. Please log in.");
      return;
    }
  
    if (!incomeSource || !incomeAmount || !incomeDate) {
      alert("Please fill in all required fields: Source, Amount, and Date.");
      return;
    }
  
    const income = {
      source: incomeSource,
      amount: parseFloat(incomeAmount),
      date: incomeDate,
    };
  
    const incomeRef = ref(database, `users/${userId}/income`);
    push(incomeRef, income)
      .then(() => {
        alert("Income added successfully!");
        setIncomeSource("");
        setIncomeAmount("");
        setIncomeDate("");
      })
      .catch((error) => {
        console.error("Error adding income:", error);
        alert("Failed to add income. Please try again.");
      });
  };
  
  

  return (
    <div className="add-transaction-container">
      <div className="forms-container">
        
        {/* Add Transaction Form */}
        <form onSubmit={handleTransactionSubmit} className="transaction-form">
          <h2>Add Transaction</h2>

          {/* Success Message for transaction */}
          {showSuccessMessage && (
            <div className="success-message">
              Transaction added successfully!
            </div>
          )}

          {/* Amount Input for transaction */}
          <div className="form-group">
            <label htmlFor="amount">Amount:</label>
            <input
              id="amount"
              type="number"
              value={amount}
              onChange={(e) => setAmount(e.target.value)}
              placeholder="Enter the amount"
              className="input-box"
              required
            />
          </div>

          {/* Description Input for transaction */}
          <div className="form-group">
            <label htmlFor="description">Transaction Description:</label>
            <input
              id="description"
              type="text"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="e.g., Amazon, Grocery"
              className="input-box"
            />
          </div>

          {/* Category Input for transaction */}
          <div className="form-group">
            <label htmlFor="category">Category:</label>
            <input
              id="category"
              type="text"
              value={category || suggestedCategory}
              onChange={(e) => setCategory(e.target.value)}
              placeholder="Select or type a category"
              className="input-box"
            />
            {suggestedCategory && !category && (
              <p className="suggested-category">Suggested Category: {suggestedCategory}</p>
            )}
          </div>

          {/* Party Involved Input */}
          <div className="form-group">
            <label htmlFor="partyInvolved">Party Involved:</label>
            <input
              id="partyInvolved"
              type="text"
              value={partyInvolved}
              onChange={(e) => setPartyInvolved(e.target.value)}
              placeholder="e.g., John Doe"
              className="input-box"
            />
          </div>

          {/* Recurring Input for transaction */}
          <div className="form-group">
            <label htmlFor="isRecurring">Recurring Transaction:</label>
            <input
              id="isRecurring"
              type="checkbox"
              checked={isRecurring}
              onChange={() => setIsRecurring(!isRecurring)}
              className="input-box"
            />
          </div>

          {isRecurring && (
            <div className="form-group">
              <label htmlFor="recurringFrequency">Recurring Frequency:</label>
              <select
                id="recurringFrequency"
                value={recurringFrequency}
                onChange={(e) => setRecurringFrequency(e.target.value)}
                className="input-box"
              >
                <option value="monthly">Monthly</option>
                <option value="weekly">Weekly</option>
                <option value="daily">Daily</option>
              </select>
            </div>
          )}

          {/* Udhar (Loan) Input for transaction */}
          <div className="form-group">
            <label htmlFor="isUdhar">Udhar (Loan):</label>
            <input
              id="isUdhar"
              type="checkbox"
              checked={isUdhar}
              onChange={() => setIsUdhar(!isUdhar)}
              className="input-box"
            />
          </div>

          {isUdhar && (
            <>
              <div className="form-group">
                <label htmlFor="loanType">Loan Type:</label>
                <select
                  id="loanType"
                  value={loanType}
                  onChange={(e) => setLoanType(e.target.value)}
                  className="input-box"
                >
                  <option value="borrow">Borrow</option>
                  <option value="lend">Lend</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="loanAmount">Amount:</label>
                <input
                  id="loanAmount"
                  type="number"
                  value={loanAmount}
                  onChange={(e) => setLoanAmount(e.target.value)}
                  placeholder="Enter loan amount"
                  className="input-box"
                />
              </div>

              <div className="form-group">
                <label htmlFor="repaymentDate">Repayment Date:</label>
                <input
                  id="repaymentDate"
                  type="date"
                  value={repaymentDate}
                  onChange={(e) => setRepaymentDate(e.target.value)}
                  className="input-box"
                />
              </div>
            </>
          )}

          {/* Date Input for transaction */}
          <div className="form-group">
            <label htmlFor="date">Date:</label>
            <input
              id="date"
              type="date"
              value={date}
              onChange={(e) => setDate(e.target.value)}
              className="input-box"
              required
            />
          </div>

          {/* Note Input for transaction */}
          <div className="form-group">
            <label htmlFor="note">Note:</label>
            <textarea
              id="note"
              value={note}
              onChange={(e) => setNote(e.target.value)}
              placeholder="Additional notes (optional)"
              className="input-box"
            ></textarea>
          </div>

          {/* Submit Button for transaction */}
          <button type="submit" className="submit-button">
            Add Transaction
          </button>
        </form>

        {/* Add Income Form */}
        <form onSubmit={handleIncomeSubmit} className="income-form">
          <h2>Add Income</h2>
          
          {/* Income Source, Amount, Date */}
          <div className="form-group">
            <label htmlFor="incomeSource">Source:</label>
            <input
              id="incomeSource"
              type="text"
              value={incomeSource}
              onChange={(e) => setIncomeSource(e.target.value)}
              placeholder="e.g., Salary, Bonus"
              className="input-box"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="incomeAmount">Amount:</label>
            <input
              id="incomeAmount"
              type="number"
              value={incomeAmount}
              onChange={(e) => setIncomeAmount(e.target.value)}
              placeholder="Enter the income amount"
              className="input-box"
              required
            />
          </div>

          <div className="form-group">
            <label htmlFor="incomeDate">Date:</label>
            <input
              id="incomeDate"
              type="date"
              value={incomeDate}
              onChange={(e) => setIncomeDate(e.target.value)}
              className="input-box"
              required
            />
          </div>

          {/* Submit Button for income */}
          <button type="submit" className="submit-button">
            Add Income
          </button>
        </form>
      </div>
    </div>
  );
};

export default AddTransaction;
