import React, { useState, useEffect } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {
  faPlus,
  faChartBar,
  faList,
  faCog,
  faUser,
  faSignOutAlt,
  faUserPlus,
} from "@fortawesome/free-solid-svg-icons";
import { Link } from "react-router-dom";
import { auth } from "./firebase"; // Ensure correct import
import { onAuthStateChanged, signOut } from "firebase/auth";
import "./Navbar.css"; // Import updated CSS file

const Navbar = () => {
  const [user, setUser] = useState(null);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
    });
    return () => unsubscribe();
  }, []);

  const handleLogout = async () => {
    try {
      await signOut(auth);
    } catch (error) {
      console.error("Logout error:", error.message);
    }
  };

  return (
    <nav className="navbar">
      <div className="links">
        <Link to="/" className="nav-item">
          <FontAwesomeIcon icon={faChartBar} />
        </Link>
        <Link to="/upcoming-investments" className="nav-item">
          <FontAwesomeIcon icon={faList} />
        </Link>
        <Link to="/add-transaction" className="nav-item">
          <FontAwesomeIcon icon={faPlus} />
        </Link>
        <Link to="/analytics" className="nav-item">
          <FontAwesomeIcon icon={faChartBar} />
        </Link>
        <Link to="/settings" className="nav-item">
          <FontAwesomeIcon icon={faCog} />
        </Link>
      </div>

      <div className="profile">
        {user ? (
          <>
            <span className="user-email">{user.email}</span>
            <button className="auth-btn logout" onClick={handleLogout}>
              <FontAwesomeIcon icon={faSignOutAlt} /> Logout
            </button>
          </>
        ) : (
          <div className="auth-buttons">
            <Link to="/login" className="auth-btn login">
              <FontAwesomeIcon icon={faUser} /> Login
            </Link>
            <Link to="/signup" className="auth-btn signup">
              <FontAwesomeIcon icon={faUserPlus} /> Signup
            </Link>
          </div>
        )}
      </div>
    </nav>
  );
};
document.addEventListener("DOMContentLoaded", function () {
  // Simulating login check (Replace this with real authentication logic)
  const isLoggedIn = localStorage.getItem("userLoggedIn") === "true";

  const loginButton = document.querySelector(".auth-btn.login");
  const signupButton = document.querySelector(".auth-btn.signup");
  const logoutButton = document.querySelector(".auth-btn.logout");

  if (isLoggedIn) {
    loginButton.style.display = "none";
    signupButton.style.display = "none";
    logoutButton.style.display = "flex"; // Show logout button when logged in
  } else {
    loginButton.style.display = "flex";
    signupButton.style.display = "flex";
    logoutButton.style.display = "none";
  }

  // Simulating Logout Click (Replace with real logout logic)
  logoutButton.addEventListener("click", function () {
    localStorage.setItem("userLoggedIn", "false");
    location.reload();
  });
});

export default Navbar;
